{"command": "python3 - <<'EOF'
from intervalset.iset import IntervalSet
import random

def canon(intervals):
    iv = sorted((s, e) for s, e in intervals if s < e)
    for (a1, a2), (b1, b2) in zip(iv, iv[1:]):
        assert a2 < b1, f"not canonical {iv}"
    return iv

random.seed(2024)
for trial in range(300):
    s = IntervalSet(); points = set()
    for step in range(200):
        a, b = sorted(random.sample(range(-20, 41), 2))
        if random.random() < 0.5:
            s.add(a, b); points.update(range(a, b))
        else:
            s.remove(a, b)
            if a != b: points.difference_update(range(a, b))
        canon(s.intervals())
        if step % 25 == 0:
            assert s.length() == len(points)
            for x in range(-20, 41, 3):
                assert s.contains(x) == (x in points)
    assert s.length() == len(points)
    for x in range(-20, 41):
        assert s.contains(x) == (x in points)
print("300 sequences x 200 interleaved add/remove ops: OK (right pieces always present, canonical at every step)")
