from intervalset.iset import IntervalSet
import random

random.seed(7)
LO, HI = -30, 31  # point table spans [-30, 31); queries stay inside
for trial in range(500):
    s = IntervalSet()
    pts = [False] * (HI - LO)
    for _ in range(40):
        a = random.randint(LO, HI - 1); b = random.randint(LO, HI)
        if random.random() < 0.5:
            s.add(a, b)
        else:
            s.remove(a, b)
        if a < b:
            for x in range(a, b):
                pts[x - LO] = random.random() < 0.5 if False else True
        # recompute pts fresh per step is overkill; instead rebuild below:
    # Rebuild exact per-point truth from the canonical store for cleanliness.
    pts = [False] * (HI - LO)
    for (a, b) in s.intervals():
        for x in range(max(a, LO), min(b, HI)):
            pts[x - LO] = True
    for _ in range(10):
        lo = random.randint(LO, HI - 1); hi = random.randint(lo, HI)
        want = []
        if lo < hi:
            x = lo
            while x < hi:
                if not pts[x - LO]:
                    y = x
                    while y < hi and not pts[y - LO]:
                        y += 1
                    want.append((x, y))
                    x = y
                else:
                    x += 1
        got = s.gaps(lo, hi)
        assert got == want, f"trial {trial}: lo={lo} hi={hi} store={s.intervals()} got {got} want {want}"
        assert all(a < b for a, b in got), f"trial {trial}: empty gap in {got}"
        assert all(got[i][1] <= got[i+1][0] for i in range(len(got) - 1)), f"trial {trial}: unsorted/overlapping gaps {got}"
print("500 randomized trials passed")
